customCSS:
.t, .history { color: #a6a69c; }
.join { color: #8a9a7b; }
.part, .quit { color: #a6a69c; }
.kick, .error { color: #c4746e; }
.notice { color: #c4b28a; }
.action { color: #a292a3; }
.mode, .nick, .topic, .server { color: #8ea4a2; }
.highlight { color: #c8c093; background-color: #223249; border-left: 3px solid #a292a3; padding-left: 8px; }
.reply { color: #a6a69c; border-left: 2px solid #8ba4b0; padding-left: 6px; }
.oper { color: #181616; background-color: #c4b28a; }
.reactions { color: #8ba4b0; background-color: #0d0c0c; }
.card { background-color: #0d0c0c; border-color: #a6a69c; }
.card-title { color: #8ba4b0; }
.card-desc { color: #a6a69c; }
.daychange { color: #a6a69c; border-color: #0d0c0c; }
